    EXPECT_CALL(*this, HandleHelp()).Times(1).WillOnce(testing::Return(true));
    return;
  }

  if (*test_case_func == &PassAPath<CatMock>) {
    const auto arg1 = args[0];
    EXPECT_CALL(*this, HandlePath(arg1))
        .Times(1)
        .WillOnce(testing::Return(true));
  }
}
